mod url_parser;

use std::env;
use std::io::{self, Write};
use url_parser::URL;

fn write_line<W: Write>(writer: &mut W, bytes: &[u8]) -> io::Result<()> {
    writer.write_all(bytes)?;
    writer.write_all(b"\n")
}

fn run() -> io::Result<()> {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        std::process::exit(1);
    }

    let input = &args[1];
    let encoded = url_parser::url_encode(input);
    let decoded = url_parser::url_decode(input);
    let parser = URL::new(format!("http://example.com/test?q={encoded}"));

    let mut stdout = io::stdout().lock();

    write_line(&mut stdout, encoded.as_bytes())?;
    write_line(&mut stdout, &decoded)?;
    write_line(&mut stdout, parser.scheme().as_bytes())?;
    write_line(&mut stdout, parser.host().as_bytes())?;
    write_line(&mut stdout, parser.path().as_bytes())?;
    write_line(&mut stdout, parser.query().as_bytes())?;

    for (key, value) in parser.query_params() {
        write_line(&mut stdout, &url_parser::url_decode(&key))?;
        write_line(&mut stdout, &url_parser::url_decode(&value))?;
    }

    Ok(())
}

fn main() {
    if run().is_err() {
        std::process::exit(1);
    }
}

